    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  return (
    <>
      <PageHeader
        title="Transactions"
        email={user.email}
        beforeTitle={
          <a
            href="/account"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Account"
          >
            <ArrowLeft className="size-4" />
          </a>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-4xl px-8 py-8 space-y-6">
        <div className="flex flex-wrap items-center gap-2">
          {(["all", "success", "pending", "failed"] as const).map((f) => (
            <Button
              key={f}
              variant={filter === f ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter(f)}
              className="capitalize"
            >
              {f}
            </Button>
          ))}

          <div className="flex-1 min-w-[200px] relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
            <Input
              placeholder="Search by name or account..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-8 h-9 text-sm"
            />
          </div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-muted-foreground">From</label>
            <Input
              type="date"
              value={dateFrom}
              onChange={(e) => setDateFrom(e.target.value)}
              className="h-9 w-[140px] text-sm"
            />
            <label className="text-xs text-muted-foreground">To</label>
            <Input
              type="date"
              value={dateTo}
              onChange={(e) => setDateTo(e.target.value)}
              className="h-9 w-[140px] text-sm"
            />
          </div>
        </div>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-4">
            <CardTitle className="text-sm font-medium">
              {filter === "all" ? "All Transactions" : `${filter.charAt(0).toUpperCase() + filter.slice(1)} Transactions`}
            </CardTitle>
            <span className="text-xs text-muted-foreground">{filtered.length} total</span>
          </CardHeader>
          <CardContent className="p-0">
            {txQuery.isLoading && (
              <div className="space-y-3 p-6">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Skeleton key={i} className="h-12 w-full rounded-md" />
                ))}
              </div>
            )}

            {txQuery.isError && (
              <div className="flex flex-col items-center gap-3 py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">{txQuery.error?.message ?? "Failed to load transactions"}</p>
                <Button variant="outline" size="sm" onClick={() => txQuery.refetch()}>
                  Retry
                </Button>
              </div>
            )}

            {!txQuery.isLoading && !txQuery.isError && filtered.length === 0 && (
              <div className="py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">
                  {transactions.length === 0
                    ? "No transactions yet. Deposit funds to get started."
                    : `No ${filter !== "all" ? filter : ""} transactions found.`}
                </p>
              </div>
            )}

            {!txQuery.isLoading && !txQuery.isError && filtered.length > 0 && (
              <>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      {table.getHeaderGroups().map((hg) => (
                        <tr key={hg.id} className="border-b border-border/50">
                          {hg.headers.map((header) => (
                            <th
                              key={header.id}
                              className="text-left text-xs font-medium text-muted-foreground px-4 py-3 cursor-pointer select-none hover:text-foreground transition-colors"
                              onClick={header.column.getToggleSortingHandler()}
                            >
                              <div className="flex items-center gap-1">
                                {flexRender(header.column.columnDef.header, header.getContext())}
                                {{
                                  asc: " \u25B2",
                                  desc: " \u25BC",
                                }[header.column.getIsSorted() as string] ?? null}
                              </div>
                            </th>
                          ))}
                        </tr>
                      ))}
                    </thead>
                    <tbody>
                      {table.getRowModel().rows.map((row) => (
                        <tr
                          key={row.id}
                          className="cursor-pointer transition-colors hover:bg-surface-hover"
                          onClick={() => window.location.href = `/transactions/${row.original.id}`}
                        >
                          {row.getVisibleCells().map((cell) => (
                            <td key={cell.id} className="px-4 py-3.5 border-b border-border/30 last:border-0">
                              {flexRender(cell.column.columnDef.cell, cell.getContext())}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex items-center justify-between px-4 py-3 border-t border-border/50">
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground">Rows per page</span>
                    <select
                      value={pageSize}
                      onChange={(e) => { setPageSize(Number(e.target.value)); setPageIndex(0) }}
                      className="h-8 rounded-md border border-input bg-background px-2 text-xs"
                    >
                      {[10, 25, 50, 100].map((s) => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>
                  <div className="flex items-center gap-1">
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={pageIndex === 0}
                      onClick={() => setPageIndex((p) => Math.max(0, p - 1))}
                      className="h-8 px-2 text-xs"
                    >
                      Prev
                    </Button>
                    {Array.from({ length: totalPages }, (_, i) => i)
                      .filter((i) => {
                        if (totalPages <= 7) return true
                        if (i === 0 || i === totalPages - 1) return true
                        if (Math.abs(i - pageIndex) <= 1) return true
                        return false
                      })
                      .map((i, idx, arr) => {
                        const showEllipsis = idx > 0 && i - arr[idx - 1] > 1
                        return (
                          <span key={i} className="flex items-center">
                            {showEllipsis && <span className="px-1 text-xs text-muted-foreground">&hellip;</span>}
                            <Button
                              variant={i === pageIndex ? "default" : "outline"}
                              size="sm"
                              onClick={() => setPageIndex(i)}
                              className="h-8 min-w-[28px] px-1 text-xs"
                            >
                              {i + 1}
                            </Button>
                          </span>
                        )
                      })}
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={pageIndex >= totalPages - 1}
                      onClick={() => setPageIndex((p) => Math.min(totalPages - 1, p + 1))}
                      className="h-8 px-2 text-xs"
                    >
                      Next
                    </Button>
                  </div>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </main>

      <PageFooter
        right={
          <span>{filtered.length} transaction{filtered.length !== 1 ? "s" : ""}</span>
        }
      />
    </>
  )
}

import { useMemo } from "react"
import { useParams, Link } from "@tanstack/react-router"
import { ArrowLeft } from "lucide-react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Badge } from "../components/ui/badge"
import { Button } from "../components/ui/button"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { useAccounts } from "@/lib/queries/accounts"
import { useTransactions } from "@/lib/queries/transactions"
import { useLedgerEntries } from "@/lib/queries/ledger"
import { getDirection } from "@/lib/direction"
import { formatCurrency } from "@/lib/utils"

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso))

export default function TransactionDetailPage() {
  const { data: session } = useSession()
  const user = session!.user
  const params = useParams({ from: "/transactions/$transactionId" })
  const transactionId = params.transactionId

  const txQuery = useTransactions(user.id)
  const accountsQuery = useAccounts(user.id)

  const transactions = useMemo(() => txQuery.data ?? [], [txQuery.data])
  const accounts = useMemo(() => accountsQuery.data ?? [], [accountsQuery.data])

  const transaction = useMemo(
    () => transactions.find((tx) => tx.id === transactionId) ?? null,
    [transactions, transactionId],
  )

  const userAccountNumbers = useMemo(() => new Set(accounts.map((a) => String(a.accountNumber))), [accounts])

  const ledgerQuery = useLedgerEntries(transactionId)
  const ledger = useMemo(() => ledgerQuery.data ?? [], [ledgerQuery.data])

  const dir = transaction ? getDirection(transaction, userAccountNumbers) : null

  const loading = txQuery.isLoading || accountsQuery.isLoading
  const error = txQuery.error ?? accountsQuery.error

  const detailRow = (label: string, value: string) => (
    <div className="flex items-baseline justify-between gap-4 py-2 border-b border-border/30 last:border-0">
      <span className="text-xs text-muted-foreground shrink-0">{label}</span>
      <span className="text-sm font-medium text-foreground text-right font-mono break-all">{value}</span>
    </div>
  )

  return (
    <>
      <PageHeader
        title={loading ? <Skeleton className="h-6 w-40" /> : "Transaction Details"}
        email={user.email}
        beforeTitle={
          <Link
            to="/transactions"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Transactions"
          >
            <ArrowLeft className="size-4" />
          </Link>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-6">
        {loading && (
          <Card>
            <CardContent className="p-6 space-y-4">
              <Skeleton className="h-4 w-24" />
              <Skeleton className="h-10 w-48" />
              <Skeleton className="h-4 w-36" />
              <Skeleton className="h-4 w-56" />
              <Skeleton className="h-4 w-40" />
            </CardContent>
          </Card>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center gap-3 py-10 text-center">
            <p className="text-sm text-muted-foreground">{error.message ?? "Failed to load transaction"}</p>
            <Link to="/transactions">
              <Button variant="default" size="sm">Back to Transactions</Button>
            </Link>
          </div>
        )}

        {!loading && !error && transaction && (
          <>
            <Card>
              <CardContent className="p-6 space-y-5">
                <div className="flex items-start justify-between">
                  <div className="space-y-1">
                    <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Amount</p>
                    <p className={`text-2xl font-semibold font-mono tracking-tight ${
                      dir === "in" ? "text-success" : "text-foreground"
                    }`}>
                      {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}
                      {formatCurrency(transaction.amount)}
                    </p>
                  </div>
                  <Badge
                    variant={transaction.status === "success" ? "default" : transaction.status === "failed" ? "destructive" : "secondary"}
                    className="text-xs"
                  >
                    {transaction.status}
                  </Badge>
                </div>

                <div className="pt-2 border-t border-border/50 space-y-0">
                  <div className="grid grid-cols-2 gap-4 pb-4 border-b border-border/30">
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">From</p>
                      <p className="text-sm font-medium text-foreground">{transaction.senderName}</p>
                      <p className="text-xs font-mono text-muted-foreground">{String(transaction.senderAccountNumber)}</p>
                    </div>
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">To</p>
                      <p className="text-sm font-medium text-foreground">{transaction.receiverName}</p>
                      <p className="text-xs font-mono text-muted-foreground">{String(transaction.receiverAccountNumber)}</p>
                    </div>
                  </div>

                  {detailRow("Transaction ID", transaction.id)}
                  {detailRow("Created", formatDate(transaction.createdAt))}
                  {transaction.updatedAt && detailRow("Updated", formatDate(transaction.updatedAt))}
                  {detailRow("Type", dir === "self" ? "Deposit" : dir === "in" ? "Incoming Transfer" : "Outgoing Transfer")}
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">Ledger Entries</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                {ledgerQuery.isLoading && (
                  <div className="space-y-3 p-6">
                    {Array.from({ length: 2 }).map((_, i) => (
                      <Skeleton key={i} className="h-10 w-full rounded-md" />
                    ))}
                  </div>
                )}
                {!ledgerQuery.isLoading && ledger.length === 0 && (
                  <div className="py-8 text-center px-6">
                    <p className="text-sm text-muted-foreground">No ledger entries available.</p>
                  </div>
                )}
                {!ledgerQuery.isLoading && ledger.length > 0 && (
                  <div className="divide-y divide-border/30">
                    {ledger.map((entry) => (
                      <div key={entry.id} className="flex items-center justify-between px-6 py-3.5">
                        <div className="flex items-center gap-3">
                          <div className={`w-2 h-2 rounded-full ${
                            entry.entryType === "debit" ? "bg-destructive" : "bg-success"
                          }`} />
                          <span className="text-sm font-medium text-foreground capitalize">{entry.entryType}</span>
                        </div>
                        <span className="text-sm font-mono font-semibold text-foreground">{formatCurrency(entry.amount)}</span>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </>
        )}
      </main>

      <PageFooter
        right={transaction && <span>ID: {transaction.id.slice(0, 8)}&hellip;</span>}
      />
    </>
  )
}

import { useState, useEffect, useMemo } from "react"
import { useSearch } from "@tanstack/react-router"
import { MoreVertical } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Select } from "../components/ui/select"
import { Skeleton } from "../components/ui/skeleton"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "../components/ui/dropdown-menu"
import ProfileSection from "../components/ProfileSection"
import WalletCardCarousel from "../components/WalletCardCarousel"
import { formatCurrency } from "@/lib/utils"
import type { IWalletTransaction, ITransaction, TBankAccountNumber } from "@/types"
import { useAccounts, useCreateAccount } from "@/lib/queries/accounts"
import { useTransfer } from "@/lib/queries/transactions"
import AddMoney from "../components/AddMoney"
import TransactionSuccess from "../components/ui/transaction-success"
import ProcessingOverlay from "../components/ui/processing-overlay"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"

export default function AccountPage() {
  const { data: session } = useSession()
  const user = session!.user
  const search = useSearch({ strict: false }) as { section?: string }
  const initialSection = search.section ?? null

  const accountsQuery = useAccounts(user.id)
  const createAccountMutation = useCreateAccount(user.id)
  const transferMutation = useTransfer(user.id)

  const accounts = useMemo(() => accountsQuery.data ?? [], [accountsQuery.data])

  const [accountName, setAccountName] = useState("")

  const [senderAccountNumber, setSenderAccountNumber] = useState<TBankAccountNumber>()
  const [receiverNumber, setReceiverNumber] = useState("")
  const [amount, setAmount] = useState("")
  const [receiverLookup, setReceiverLookup] = useState<{ name: string; accountNumber: TBankAccountNumber } | null>(null)
  const [lookingUp, setLookingUp] = useState(false)

  useEffect(() => {
    if (initialSection === "deposit" || initialSection === "transfer") {
      const id = initialSection === "deposit" ? "deposit-section" : "transfer-section"
      const el = document.getElementById(id)
      if (el) el.scrollIntoView({ behavior: "smooth" })
    }
  }, [initialSection])

  useEffect(() => {
    if (!receiverNumber.trim() || receiverNumber.length < 8) {
      setReceiverLookup(null)
      return
    }
    const timer = setTimeout(async () => {
      setLookingUp(true)
      try {
        const res = await fetch(`/api/wallet/accounts/by-number/${encodeURIComponent(receiverNumber.trim())}`)
        const json = await res.json()
        if (json.ok) {
          setReceiverLookup({
            accountNumber: json.data.accountNumber,
            name: json.data.name,
          })
        }
      } catch {
        setReceiverLookup(null)
      } finally {
        setLookingUp(false)
      }
    }, 400)
    return () => clearTimeout(timer)
  }, [receiverNumber])

  const handleCreateAccount = (e: React.FormEvent) => {
    e.preventDefault()
    if (!accountName.trim()) return

    const accountNumber = String(Math.floor(Math.random() * 9_000_000_000_000) + 1_000_000_000_000) as unknown as TBankAccountNumber

    createAccountMutation.mutate(
      { name: accountName.trim(), accountNumber, balance: 0 },
      {
        onSuccess: () => {
          setAccountName("")
        },
      },
    )
  }

  const handleTransfer = (e: React.FormEvent) => {
    e.preventDefault()
    if (!senderAccountNumber || !receiverLookup || !amount.trim()) return

    const sender = accounts.find((a) => a.accountNumber === senderAccountNumber)

    transferMutation.mutate(
      {
        senderAccountNumber: String(senderAccountNumber),
        senderName: sender?.name ?? "Unknown",
        receiverAccountNumber: String(receiverLookup.accountNumber),
        receiverName: receiverLookup.name,
        amount: Number.parseFloat(amount),
      },
      {
        onSuccess: (data) => {
          setSenderAccountNumber(data.senderAccountNumber as unknown as TBankAccountNumber)
          setReceiverNumber("")
          setAmount("")
          setReceiverLookup(null)
        },
      },
    )
  }

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <PageHeader
        title="Account"
        email={user.email}
        actions={
          <>
            <Button variant="outline" size="sm" onClick={() => accountsQuery.refetch()} disabled={accountsQuery.isLoading}>
              Refresh
            </Button>
            <DropdownMenu>
              <DropdownMenuTrigger className="flex items-center justify-center w-8 h-8 rounded-md border border-input bg-background hover:bg-accent hover:text-accent-foreground">
                <MoreVertical className="size-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent>
                <DropdownMenuItem onClick={() => window.location.href = "/account/settings"}>
                  Edit
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => window.location.href = "/account/transactions"}>
                  Transactions
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={handleSignOut}>
                  Sign Out
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </>
        }
      />

      <main className="grid grid-cols-2 gap-6 mx-auto w-full px-8 py-8 space-y-6">
        <div className="space-y-6 flex flex-col px-6 w-full mx-auto">
          <ProfileSection />

          <Card className="w-full mx-auto">
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>Wallet Accounts</CardTitle>
              <span className="text-xs text-muted-foreground">{accounts.length} total</span>
            </CardHeader>
            <CardContent className="space-y-3 w-full">
              {accountsQuery.isLoading && (
                <div className="space-y-3">
                  {Array.from({ length: 2 }).map((_, i) => (
                    <Skeleton key={i} className="h-16 w-full rounded-lg" />
                  ))}
                </div>
              )}

              {accountsQuery.isError && (
                <div className="flex flex-col items-center gap-3 py-6 text-center">
                  <p className="text-sm text-muted-foreground">{accountsQuery.error?.message ?? "Failed to load accounts"}</p>
                  <Button variant="outline" size="sm" onClick={() => accountsQuery.refetch()}>
                    Retry
                  </Button>
                </div>
              )}

              {!accountsQuery.isLoading && !accountsQuery.isError && accounts.length === 0 && (
                <div className="py-6 text-center">
                  <p className="text-sm text-muted-foreground">No accounts yet. Create one below.</p>
                </div>
              )}

              {!accountsQuery.isLoading && !accountsQuery.isError && accounts.length > 0 && (
                <WalletCardCarousel accounts={accounts} />
              )}

              <form onSubmit={handleCreateAccount} className="space-y-3 pt-4 border-t border-border">
                <div className="space-y-1.5">
                  <Label htmlFor="account-name">New Account Name</Label>
                  <Input
                    id="account-name"
                    placeholder="e.g. Checking, Savings"
                    value={accountName}
                    onChange={(e) => setAccountName(e.target.value)}
                    disabled={createAccountMutation.isPending}
                  />
                </div>
                {createAccountMutation.isError && (
                  <p className="text-sm text-destructive">{createAccountMutation.error?.message ?? "Failed to create account"}</p>
                )}
                <Button type="submit" disabled={createAccountMutation.isPending || !accountName.trim()} className="w-full">
                  {createAccountMutation.isPending ? "Creating..." : "Create Account"}
                </Button>
              </form>
            </CardContent>
          </Card>
        </div>

        <div className="space-y-6 flex flex-col px-6 w-full mx-auto">
          <AddMoney accounts={accounts} userId={user.id} onDeposit={() => accountsQuery.refetch()} />

          <Card id="transfer-section" className="w-full mx-auto">
            <CardHeader className="card-header-accent">
              <CardTitle>Send Money</CardTitle>
            </CardHeader>
            <CardContent>
              {transferMutation.data && !transferMutation.isPending ? (
                <TransactionSuccess
                  title="Transfer completed"
                  amount={formatCurrency(transferMutation.data.amount)}
                  description={`${transferMutation.data.senderName} \u2192 ${transferMutation.data.receiverName}`}
                  actionLabel="Send another"
                  onReset={() => transferMutation.reset()}
                />
              ) : (
                <form onSubmit={handleTransfer} className="space-y-4">
                  <div className="space-y-1.5">
                    <Label htmlFor="sender">From</Label>
                    <Select
                      id="sender"
                      value={senderAccountNumber as unknown as number}
                      onChange={(e) => setSenderAccountNumber(e.target.value as unknown as TBankAccountNumber)}
                      required
                    >
                      <option value="" disabled>Select an account</option>
                      {accounts.map((acc) => (
                        <option key={acc.id} value={acc.accountNumber as unknown as number}>
                          {acc.name} ({acc.accountNumber}) · {formatCurrency(acc.balance)}
                        </option>
                      ))}
                    </Select>
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="receiver">To (account number)</Label>
                    <Input
                      id="receiver"
                      placeholder="e.g. 1000000000000"
                      value={receiverNumber}
                      onChange={(e) => setReceiverNumber(e.target.value)}
                    />
                    {lookingUp && (
                      <p className="text-xs text-muted-foreground">Looking up account...</p>
                    )}
                    {receiverLookup && !lookingUp && (
                      <p className="text-xs font-medium text-success">{receiverLookup.name}</p>
                    )}
                    {!receiverLookup && !lookingUp && receiverNumber.length >= 8 && (
                      <p className="text-xs text-muted-foreground">No account found with that number</p>
                    )}
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="amount">Amount (USD)</Label>
                    <Input
                      id="amount"
                      type="number"
                      step="0.01"
                      min="0.01"
                      placeholder="0.00"
                      value={amount}
                      onChange={(e) => setAmount(e.target.value)}
                    />
                  </div>

                  {transferMutation.isError && (
                    <p className="text-sm text-destructive">{transferMutation.error?.message ?? "Failed to send transfer"}</p>
                  )}

                  <Button
                    type="submit"
                    disabled={!senderAccountNumber || !receiverLookup || !amount.trim() || Number(amount) <= 0}
                    className="w-full"
                  >
                    Send Money
                  </Button>
                </form>
              )}
            </CardContent>
          </Card>
        </div>
      </main>

      <PageFooter right={<span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>} />

      {transferMutation.isPending && (
        <ProcessingOverlay
          amount={formatCurrency(amount)}
          description={`${accounts.find((a) => a.accountNumber === senderAccountNumber)?.name ?? "Sender"} \u2192 ${receiverLookup?.name ?? "Receiver"}`}
          label="Processing transfer"
        />
      )}
    </>
  )
}

import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { useNotificationPrefs, useTogglePreference } from "@/lib/queries/notificationPrefs"

const EVENT_LABELS: Record<string, string> = {
  deposit: "Deposits",
  transfer_incoming: "Money Received",
  transfer_outgoing: "Money Sent",
}

const EVENT_DESCRIPTIONS: Record<string, string> = {
  deposit: "When money is added to your account",
  transfer_incoming: "When someone sends you money",
  transfer_outgoing: "When you send money to someone",
}

export default function NotificationPreferencesPage() {
  const { data: session } = useSession()
  const user = session!.user

  const prefsQuery = useNotificationPrefs(user.id)
  const toggleMutation = useTogglePreference(user.id)

  const preferences = prefsQuery.data ?? []
  const allEventTypes = ["deposit", "transfer_incoming", "transfer_outgoing"]
  const preferenceMap = new Map(preferences.map((p) => [p.eventType, p]))

  return (
    <>
      <PageHeader
        title="Notification Preferences"
        email={user.email}
      />

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6">
        {prefsQuery.isLoading && (
          <div className="flex flex-col gap-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <Skeleton key={i} className="h-20 w-full rounded-lg" />
            ))}
          </div>
        )}

        {prefsQuery.isError && (
          <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
            <p className="text-muted-foreground">{prefsQuery.error?.message ?? "Failed to load preferences"}</p>
            <Button variant="outline" onClick={() => prefsQuery.refetch()}>Retry</Button>
          </div>
        )}

        {!prefsQuery.isLoading && !prefsQuery.isError && (
          <div className="flex flex-col gap-2">
            {allEventTypes.map((eventType) => {
              const pref = preferenceMap.get(eventType)
              const enabled = pref?.enabled ?? true
              return (
                <Card key={eventType}>
                  <CardContent className="flex items-center justify-between p-6">
                    <div className="space-y-0.5">
                      <p className="text-sm font-medium text-foreground">{EVENT_LABELS[eventType]}</p>
                      <p className="text-xs text-muted-foreground">{EVENT_DESCRIPTIONS[eventType]}</p>
                    </div>
                    <button
                      type="button"
                      role="switch"
                      aria-checked={enabled}
                      disabled={toggleMutation.isPending}
                      onClick={() => toggleMutation.mutate({ eventType, enabled: !enabled })}
                      className={`relative h-6 w-11 rounded-full transition-colors ${
                        toggleMutation.isPending ? "opacity-50 pointer-events-none" : ""
                      } ${
                        enabled ? "bg-primary" : "bg-input"
                      }`}
                    >
                      <span
                        className={`block h-5 w-5 rounded-full bg-background shadow-sm transition-transform ${
                          enabled ? "translate-x-[22px]" : "translate-x-[2px]"
                        }`}
                      />
                    </button>
                  </CardContent>
                </Card>
              )
            })}
          </div>
        )}
      </main>

      <PageFooter
        left="Wave Notification Center"
        right={<span>Preferences</span>}
      />
    </>
  )
}

import { useState, useMemo } from "react"
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
} from "@tanstack/react-table"
import { Badge } from "./ui/badge"
import { Skeleton } from "./ui/skeleton"
import { formatCurrency } from "../lib/utils"
import { getDirection } from "@/lib/direction"
import type { ITransaction } from "@/types"

interface DataTableProps {
  data: ITransaction[]
  userAccountNumbers: Set<string>
  loading?: boolean
  emptyMessage?: string
  onRowClick?: (tx: ITransaction) => void
}

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

export default function DataTable({ data, userAccountNumbers, loading, emptyMessage, onRowClick }: DataTableProps) {
  const columnHelper = createColumnHelper<ITransaction>()

  const columns = useMemo(
    () => [
      columnHelper.accessor("createdAt", {
        header: "Date",
        cell: (info) => (
          <span className="text-sm text-muted-foreground whitespace-nowrap">
            {formatDate(info.getValue())}
          </span>
        ),
      }),
      columnHelper.display({
        id: "direction",
        header: "",
        cell: ({ row }) => {
          const dir = getDirection(row.original, userAccountNumbers)
          return (
            <div className="shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
              {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
            </div>
          )
        },
      }),
      columnHelper.accessor("senderName", {
        header: "Counterparty",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx, userAccountNumbers)
          const label = dir === "self" ? "Deposit" : dir === "in" ? `From ${tx.senderName}` : `To ${tx.receiverName}`
          return (
            <div className="min-w-0">
              <p className="text-sm font-medium text-foreground truncate">{label}</p>
            </div>
          )
        },
      }),
      columnHelper.accessor("amount", {
        header: "Amount",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx, userAccountNumbers)
          return (
            <span className={`text-sm font-mono font-semibold whitespace-nowrap ${
              dir === "in" ? "text-success" : dir === "out" ? "text-foreground" : "text-foreground"
            }`}>
              {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}{formatCurrency(tx.amount)}
            </span>
          )
        },
      }),
      columnHelper.accessor("status", {
        header: "Status",
        cell: (info) => (
          <Badge
            variant={info.getValue() === "success" ? "default" : info.getValue() === "failed" ? "destructive" : "secondary"}
            className="text-[10px] px-1.5 py-0 whitespace-nowrap"
          >
            {info.getValue()}
          </Badge>
        ),
      }),
    ],
    [columnHelper, userAccountNumbers],
  )

  const [sorting, setSorting] = useState<SortingState>([{ id: "createdAt", desc: true }])

  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  if (loading) {
    return (
      <div className="space-y-3 p-4">
        {Array.from({ length: 5 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full rounded-md" />
        ))}
      </div>
    )
  }

  if (data.length === 0) {
    return (
      <div className="py-10 text-center">
        <p className="text-sm text-muted-foreground">{emptyMessage ?? "No transactions yet."}</p>
      </div>
    )
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full">
        <thead>
          {table.getHeaderGroups().map((hg) => (
            <tr key={hg.id} className="border-b border-border/50">
              {hg.headers.map((header) => (
                <th
                  key={header.id}
                  className="text-left text-xs font-medium text-muted-foreground px-4 py-3 cursor-pointer select-none hover:text-foreground transition-colors"
                  onClick={header.column.getToggleSortingHandler()}
                >
                  <div className="flex items-center gap-1">
                    {flexRender(header.column.columnDef.header, header.getContext())}
                    {{
                      asc: " \u25B2",
                      desc: " \u25BC",
                    }[header.column.getIsSorted() as string] ?? null}
                  </div>
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr
              key={row.id}
              className={`transition-colors ${onRowClick ? "cursor-pointer hover:bg-surface-hover" : "hover:bg-surface-hover"}`}
              onClick={() => onRowClick?.(row.original)}
            >
              {row.getVisibleCells().map((cell) => (
                <td key={cell.id} className="px-4 py-3 border-b border-border/30 last:border-0">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}
